<?php
 require_once(__DIR__ . '/../../init.php'); class med_common_msgSend { const TASK_NAME = 'msgSend', DEBUG = true, DEBUG_PLUG = true, MED_COUPON_SET = 'medCoupon-set', MED_COUPON_CANCEL = 'medCoupon-cancel', DATE_FORMAT = 'c', OPTIONS_TTL = 60, MAX_ATTEMPTS = 5; private $db, $extraSettings, $listEvent, $listMessage, $currTime, $results = [], $sendTime; public function __construct() { $this->currTime = new DateTime(); } public function __destruct() { unset($this->currTime); } public function mailing() { if (empty($this->loadSettings())) { return $this->results; } $this->prepareEvents(); return $this->mailingMessage(); } public function prepareEvents() { $this->sessionConnectDb(); $this->db->beginTransaction(); $this->listEvent = $this->getEvents(); $this->log('[1]Обработка событий...'); try { $this->createSending(); $this->insertSending(); $this->deleteEvents(); $this->db->commit(); } catch (Throwable $e) { $this->db->rollback(); $this->results[4] = $this->results[1] = 'Критическая ошибка при обработки событий!'; $this->log("[1]Обработка событий... Критическая ошибка \r\n" . print_r($e, true), 2); throw $e; } $this->log('[1]Обработка событий... OK'); } private function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } private function sessionConnectDb() { return $this->db ?: $this->db = connectDb(); } private function loadSettings() { $extra = $this->extraSettings = readExtraSettings(getSessionValue('config'), self::TASK_NAME); $this->log('[0]Чтение параметров...'); $this->log(print_r($extra, true)); if (empty($extra)) { $this->results[0] = 'Ошибка чтения параметров [отсутствуют параметры]'; $this->log('[0]Чтение параметров... Ошибка [отсутствуют параметры]', 2); return false; } elseif (empty($extra->active)) { $this->results[0] = 'Ошибка чтения параметров [обмен данными запрещен]'; $this->log('[0]Чтение параметров... Ошибка [обмен данными запрещен]', 1); return false; } elseif (empty($extra->url)) { $this->results[0] = 'Ошибка чтения параметров [не указан URL адрес]'; $this->log('[0]Чтение параметров... Ошибка [не указан URL адрес]', 2); return false; } elseif (empty($extra->senderName)) { $this->results[0] = 'Ошибка чтения параметров [не указан отправитель]'; $this->log('[0]Чтение параметров... Ошибка [не указан отправитель]', 2); return false; } $this->log('[0]Чтение параметров... ОК'); return true; } private function getEvents() { $sql = <<<"EOT"
