  and MR.active = 1
  and ME.changeTime < '{$this->currTime->format(self::DATE_FORMAT)}' -- только актуальные
EOT;
return selectSql($this->db, $sql, null, PDO::FETCH_CLASS); } private function insertSending() { return insertSql($this->db, 'MsgSend', $this->listEvent, 'msgRuleCode type source userCode messageText status startTime finishTime stage attemptsRemain manCode', 'ruleId      type source userId   message            startTime finishTime stage attemptCnt     manId', '?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?', 'sendId', false); } private function deleteEvents() { return deleteSql($this->db, 'MsgEvent', 'msgEventCode', $this->listEvent, 'eventId', false); } private function createSending() { $this->log('   Создание сообщений для отправки...'); foreach ($this->listEvent as &$item) { $data = safe_json_decode($item->data); try { $this->setSendingPeriod($item, $data); $this->prepareSettings($item, $data); $this->createSendingMessage($item, $data); $this->setSendingMan($item, $data); } catch (Throwable $e) { $item->status = -5; $info = $this->createEventInfo($item, $data); $this->results[1][] = "Ошибка обработки события {$this->type}({$item->eventId}))"; $this->log("   Ошибка обработки события... /r/n{$info}/r/n{$e}", 2); } finally { $this->clearData($item); } } $this->log('   Создание сообщений для отправки... OK'); } private function createEventInfo($item, $data) { $info = "событие:   {$item->type}({$item->eventId})"; switch ($item->type) { case self::MED_COUPON_SET: case self::MED_COUPON_CANCEL: return "{$info}/r/n{$this->createInfoCoupon($data)}"; } return $info; } private function createInfoCoupon($data) { return <<<"EOT"
посещение:  {$data->visitTime}({$data->medCouponCode})
пациент:    {$data->medPatientFIO}({$data->medPatientCode})
врач:       {$data->medDoctorFIO}({$data->medDoctorCode})
EOT;
} private function prepareSettings(&$item, $data) { $item->attemptCnt = $this->attemptCnt ?? $this->extraSettings->repeatAttempt ?? self::MAX_ATTEMPTS; } private function setSendingPeriod(&$item, $data) { switch ($item->type) { case self::MED_COUPON_SET: case self::MED_COUPON_CANCEL: $this->createSendingPeriodCoupon($item, $data); default: break; } } private function clearData(&$item) { unset($item->data); unset($item->template); unset($item->startPoint); unset($item->startShift); unset($item->changeTime); } private function correctDate($date) { return str_replace('.', '-', $date); } private function createSendingPeriodCoupon(&$item, $json) { $isStart = $item->startPoint === 1; $visitTime = $this->correctDate($json->visitTime); $direction = $isStart ? '+' : '-'; $item->startTime = (new DateTime($isStart ? $item->changeTime : $visitTime)) ->modify("{$direction}{$item->startShift} sec") ->format(self::DATE_FORMAT); $item->finishTime = $visitTime; } private function createSendingMessage(&$item, $data) { switch ($item->type) { case self::MED_COUPON_SET: case self::MED_COUPON_CANCEL: $this->createMessageCoupon($item, $data); break; default: break; } } private function getMacrosMap($type) { switch ($type) { case self::MED_COUPON_SET: case self::MED_COUPON_CANCEL: return [ '{$patient}' => 'medPatientFIO', '{$visitTime}' => 'VisitTime', '{$doctor}' => 'medDoctorFIO', '{$cabinet}' => 'cabinet' ]; default: return []; } } private function prepareMacrosMap($list, $json) { $arr = []; foreach ($list as $key => $value) { $arr[preg_quote("/{$key}/")] = $json->{$value} ?? null; } return $arr; } private function prepareDataCoupon(&$json) { foreach ($json as $key => $value) { if ($key === 'visitTime') { $json->{$key} = $this->correctDate($value); } else if ($key === 'medPatientFIO') { $json->{$key} = transformFio($value, 'fio'); } else if ($key === 'medDoctorFIO') { $json->{$key} = transformFio($value, 'fio'); } } } private function createMessageCoupon(&$item, $json) { $this->prepareDataCoupon($json); $map = $this->prepareMacrosMap($this->getMacrosMap(self::MED_COUPON_SET), $json); $item->message = preg_replace(array_keys($map), array_values($map), $item->template); } private function setSendingMan(&$item, $data) { $item->manId = $data->manCode; } private function mailingMessage() { $this->listMessage = $this->getSending(); $this->prepareMailing(); return $this->sending(); } private function prepareMailing() { foreach ($this->listMessage as &$item) { $this->checkPhone($item); $this->checkBadTime($item); $this->checkBadStage($item); } $this->updateSendRecord(); } private function isSending($item) { return $item->status === 1; } private function checkPhone(&$item) { if ($this->isSending($item) && empty($item->phone)) { $item->status = -4; } } private function checkBadTime(&$item) { if ($this->isSending($item)) { if (new DateTime($item->finishTime) < $this->currTime) { $item->status = -2; } } } private function checkBadStage(&$rec) { if ($this->isSending($rec)) { $maxStage = $rec->stage; foreach ($this->listMessage as &$item) { if ($item->id !== $rec->id && $this->checkActual($item) && $item->type === $rec->type && $item->source === $rec->source && $item->stage > $maxStage) { $maxStage = $item->stage; $rec->status = -3; } } } } private function checkActual($item) { return $this->isSending($item) && new DateTime($item->startTime) < $this->currTime && $this->currTime < new DateTime($item->finishTime); } private function sending() { $this->log('[2]Отправка сообщений...'); $this->sendTime = (new DateTime())->format(self::DATE_FORMAT); if (empty($result = $this->sendQueryToAPI($this->createObjectSending()))) { $this->log('   Отправка запроса... Ошибка [неверные параметры отправки]', 2); $this->results[2] = 'Ошибка отправки сообщений'; $this->setFailSendingAll(); return $this->results; } $this->log('   Отправка запроса... ОК'); $this->log('[2]Отправка сообщений... ОК'); $this->log('[3]Обработка ответа...'); $this->log('   Обработка результата...'); if ($result['status'][1] === '200') { $messages = safe_json_decode($result['body']); foreach ($this->listMessage as &$item) { if (($message = $this->findMessage($messages, $item->id))) { $this->setDoneSending($item, $message); $this->writeLogSending($item, false); } else { $this->setFailSending($item); $this->writeLogSending($item); } } $this->updateSendRecord(); } else { $this->log('   Обработка результата... Ошибка [неверный ответ сервера]'); $this->results[3] = 'Ошибка обработки результата отправки'; $this->setFailSendingAll(); } $this->log('   Обработка результата... OK'); $this->log('[3]Обработка ответа... OK'); return $this->results; } private function getStatus($code) { switch ($code) { case -1: return 'Исчерпание попыток отправки'; case -2: return 'Отмена по таймауту'; case -3: return 'Отмена отправки по очередности'; case -4: return 'Отсутствует номер телефона для отправки'; default: return 'Успешно отправлен'; } } private function writeLogSending($item, $fail = true) { $status = $fail ? 'Повторная отправка' : $this->getStatus($item->status); $this->log(<<<"EOT"
\r\n
сообщение:  {$item->id}
правило:    {$item->type} ({$item->ruleId})
получатель: {$item->manId} ({$item->phone})
отправка:   {$item->sendTime}
текст:      {$item->message}
статус:     {$status}
EOT)
; } private function findMessage($messages, $id) { foreach ($messages as $message) { if ($message->extra_id === $id) { return $message; } } return false; } private function setDoneSending(&$item, $message) { $item->attemptCnt -= 1; $item->sendTime = $this->sendTime; $item->status = 0; $item->providerId = $message->message_id; } private function setFailSending(&$item) { $item->attemptCnt -= 1; if ($item->attemptCnt === 0) { $this->status = -1; } $shift = $item->repeatShift ?? $this->extraSettings->repeatInterval; $item->startTime = (new DateTime($item->startTime)) ->modify("+{$shift} sec") ->format(self::DATE_FORMAT); $item->sendTime = $this->sendTime; } private function setFailSendingAll() { foreach ($this->listMessage as &$item) { $this->setFailSending($item); $this->writeLogSending($item); } $this->updateSendRecord(); } private function sendQueryToAPI($data) { $this->log('   Инициализация подключения...'); if ($params = httpCreateParam($this->extraSettings)) { $method = $this->getMethod(); $this->log('   Инициализация подключения... OK'); $params->request_method = $method; $params->request_content = json_encode($data, JSON_UNESCAPED_UNICODE); $params->headers['Content-Type'] = 'application/json'; $params->debug = self::DEBUG; $this->log('   Отправка запроса...'); $this->log('Отправка'); $this->log(print_r($params, true)); if (self::DEBUG_PLUG) { $obj = print_r($data, true); $this->log(<<<"EOT"
\r\n                
################ Отправляемые данные. Тест ################
{$obj}            
################ Отправляемые данные. Тест ################                
EOT)
; return false; } return httpPOST($params); } $this->log('   Инициализация подключения... Ошибка', 1); return false; } private function getMethod() { return 'POST'; } private function createArrayMessages() { $messages = []; foreach ($this->listMessage as $item) { if ($this->checkActual($item)) { $messages[] = [ 'phone_number' => $item->phone, 'extra_id' => $item->id, 'text' => $item->message ]; } } return $messages; } private function createObjectSending() { $obj = new stdClass(); $obj->messages = $this->createArrayMessages(); if (!empty($this->extraSettings->callbackUrl)) { $obj->callback_url = $this->extraSettings->callbackUrl; } if (!empty($this->extraSettings->organizationTag)) { $obj->tag = $this->extraSettings->organizationTag; } $obj->channels = $this->getChannels(); $obj->channel_options = $this->getChannelOptions(); return $obj; } private function getChannels() { return ['sms']; } private function getChannelOptions() { $obj = new stdClass(); $obj->sms = $this->getSMSOptions(); return $obj; } private function getSMSOptions() { $obj = new stdClass(); $obj->alpha_name = $this->extraSettings->senderName; $obj->ttl = self::OPTIONS_TTL; return $obj; } private function updateSendRecord() { try { updateSql($this->db, 'MsgSend', 'msgSendCode', $this->listMessage, 'status attemptsRemain providerId startTime sendTime', 'status attemptCnt providerId startTime sendTime'); } catch (Throwable $e) { $this->log("   Ошибка обновления таблицы MsgSend\r\n" . print_r($e, true)); } return true; } private function getSending() { $sql = <<<"EOT"
select
       MS.msgSendCode "id",
       MS.attemptsRemain "attemptCnt",
       MS.startTime "startTime",
       MS.finishTime "finishTime",
       MS.manCode "manId",
       MS.messageText "message",
